import java.util.*;
import java.util.concurrent.*;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in);int n=s.nextInt();String[] words=new String[n];for(int i=0;i<n;i++)words[i]=s.next();Map<String,Integer> counts=new ConcurrentHashMap<>();List<Thread> ts=new ArrayList<>();for(String w:words)ts.add(new Thread(()->counts.merge(w,1,Integer::sum)));ts.forEach(Thread::start);for(Thread t:ts)t.join();new TreeMap<>(counts).forEach((k,v)->System.out.println(k+"="+v)); } }

