import java.util.*;
import java.util.concurrent.atomic.*;
class Account { private int balance; Account(int balance){this.balance=balance;} synchronized boolean withdraw(int amount){if(balance<amount)return false;balance-=amount;return true;} synchronized int balance(){return balance;} }
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in);int initial=s.nextInt(),requests=s.nextInt(),amount=s.nextInt();Account a=new Account(initial);AtomicInteger success=new AtomicInteger();List<Thread> ts=new ArrayList<>();for(int i=0;i<requests;i++)ts.add(new Thread(()->{if(a.withdraw(amount))success.incrementAndGet();}));ts.forEach(Thread::start);for(Thread t:ts)t.join();System.out.println("balance="+a.balance());System.out.println("success="+success.get());} }
